INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('86010087-df4f-4662-b028-8a2b3ef59bd4', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'Segundo as regras estabelecidas pela Constituição Federal de 1988, nos Municípios de até 15 mil habitantes o número máximo de vereadores será de:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Flores da Cunha - RS / Enfermeiro / Questão: 20', 'O art. 29, IV, "a", da CF estabelece que municípios com até 15.000 habitantes terão o número máximo de 9 (nove) vereadores, a primeira faixa da tabela progressiva instituída pela EC 58/2009.', 1, true),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'Considerando as disposições da Constituição Federal sobre os Tribunais de Contas, bem como a jurisprudência do Supremo Tribunal Federal sobre esse tema, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Lajeado - RS / Procurador / Questão: 27', 'É o Município (e não o Estado) o legitimado para executar o crédito decorrente de multa aplicada pelo TCE a agente público municipal, por se tratar de dano ao erário municipal. A C erra ao afirmar que o TCU atua com auxílio do Senado — na verdade, é o Congresso Nacional quem exerce o controle externo com auxílio do TCU (art. 71, caput). A D inverte a competência: a sustação primária do contrato é atribuição da própria Casa Legislativa, cabendo ao TCU apenas comunicar se não atendida.', 2, true),
('123df1f2-4172-42c4-b14b-9c13389f986d', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'Segundo estabelece o Art. 31 da Constituição Federal: "A fiscalização do Município será exercida pelo Poder ____________ Municipal, mediante controle externo, e pelos sistemas de controle interno do Poder ___________ Municipal, na forma da lei". Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Salto do Jacuí Prefeitura de Salto do Jacui - RS / Agente de Controle Interno / Questão: 38', 'O texto literal do art. 31, caput, é: "A fiscalização do Município será exercida pelo Poder Legislativo Municipal, mediante controle externo, e pelos sistemas de controle interno do Poder Executivo Municipal, na forma da lei".', 3, true),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'O município é regido por lei orgânica, votada em dois turnos, com o interstício mínimo de _______ e aprovada por ________ dos membros da Câmara Municipal, que a promulgará, atendidos os princípios estabelecidos na Constituição Federal.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Iraí - RS / Procurador Municipal / Questão: 25', 'O art. 29, caput, exige que a Lei Orgânica seja votada em dois turnos, com interstício mínimo de dez dias, e aprovada por dois terços dos membros da Câmara Municipal.', 4, true),
('ed28c085-067a-433a-984e-b093f809ca9e', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'O Prefeito e o Vice-Prefeito serão eleitos para cumprimento de mandato de:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Faxinal do Soturno Prefeitura - RS / Eletricista / Questão: 24', 'O art. 29, I, da CF fixa em quatro anos o mandato do Prefeito e do Vice-Prefeito.', 5, true),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'O Tema 145 do STF está assim ementado: "O município é competente para legislar sobre o meio ambiente com a União e o Estado, no limite do seu interesse local e desde que tal regramento seja harmônico com a disciplina estabelecida pelos demais entes federados (Art. 24, VI, c/c 30, I e II, da Constituição Federal)". Considerando a lei municipal objeto da controvérsia que originou o Tema 145 do STF, bem como o teor da respectiva decisão, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Prefeitura de Porto Alegre - RS / Procurador Municipal / Questão: 79', 'O Tema 145 do STF tratou da lei estadual paulista que estabeleceu cronograma progressivo de eliminação da queima da palha de cana-de-açúcar, com substituição por mecanização, reconhecendo sua validade com base na competência concorrente ambiental (art. 24, VI) combinada com o interesse local (art. 30, I e II).', 6, true),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', '16808ffc-c67f-4363-bf66-d6d4fcc364dc', 'De acordo com o disposto na Constituição Federal, compete aos Municípios: I. Criar, organizar e suprimir distritos, observada a legislação estadual.II. Manter, com a cooperação técnica e financeira da união, do estado e de outros municípios, programas de educação infantil e de ensino fundamental.III. Prestar, com a cooperação técnica e financeira da união, do estado, e de outros municípios serviços de atendimento à saúde da população.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2020 / Prefeitura de Imbé Prefeitura - RS / Auditor Fiscal da Receita Municipal / Questão: 23', 'Apenas a I reproduz fielmente o art. 30, IV. As assertivas II e III alteram o texto original dos incisos VI e VII do art. 30, que mencionam cooperação apenas da União e do Estado, sem incluir "de outros municípios".', 7, true);
INSERT INTO public.questao_alternativas (questao_id, letra, texto, correta, ordem) VALUES
('86010087-df4f-4662-b028-8a2b3ef59bd4', 'A', '7.', false, 0),
('86010087-df4f-4662-b028-8a2b3ef59bd4', 'B', '9.', true, 1),
('86010087-df4f-4662-b028-8a2b3ef59bd4', 'C', '11.', false, 2),
('86010087-df4f-4662-b028-8a2b3ef59bd4', 'D', '13.', false, 3),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', 'A', 'A inércia do Tribunal de Contas estadual em emitir parecer prévio dentro do prazo de 90 dias impede o Poder Legislativo de julgar as contas do chefe do Poder Executivo local.', false, 0),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', 'B', 'O município prejudicado é o legitimado para a execução de crédito decorrente de multa aplicada por Tribunal de Contas estadual a agente público municipal em razão de danos causados ao erário municipal.', true, 1),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', 'C', 'O controle externo, nele compreendido a fiscalização contábil, financeira, orçamentária, operacional e patrimonial da União, será exercido pelo Tribunal de Contas da União, com auxílio do Senado Federal.', false, 2),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', 'D', 'Compete ao Tribunal de Contas da União sustar, se não atendido, a execução do contrato impugnado, comunicando a decisão à Câmara dos Deputados e ao Senado Federal.', false, 3),
('1cf54eaa-0790-4dc2-9862-cb8fe3d38567', 'E', 'É inconstitucional lei estadual, de iniciativa parlamentar, que altera a destinação dos valores arrecadados com a cobrança de multas aplicadas pelo Tribunal de Contas.', false, 4),
('123df1f2-4172-42c4-b14b-9c13389f986d', 'A', 'Executivo – Executivo.', false, 0),
('123df1f2-4172-42c4-b14b-9c13389f986d', 'B', 'Executivo – Legislativo.', false, 1),
('123df1f2-4172-42c4-b14b-9c13389f986d', 'C', 'Legislativo – Executivo.', true, 2),
('123df1f2-4172-42c4-b14b-9c13389f986d', 'D', 'Hierárquico – Judiciário.', false, 3),
('123df1f2-4172-42c4-b14b-9c13389f986d', 'E', 'Legislativo – Legislativo.', false, 4),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', 'A', 'seis meses – metade.', false, 0),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', 'B', '45 dias – três quartos.', false, 1),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', 'C', '30 dias – maioria.', false, 2),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', 'D', '10 dias – dois terços.', true, 3),
('40b547ac-51b5-46fa-8f0f-afd50b6b9a03', 'E', '5 dias – unanimidade.', false, 4),
('ed28c085-067a-433a-984e-b093f809ca9e', 'A', '2 anos.', false, 0),
('ed28c085-067a-433a-984e-b093f809ca9e', 'B', '3 anos.', false, 1),
('ed28c085-067a-433a-984e-b093f809ca9e', 'C', '4 anos.', true, 2),
('ed28c085-067a-433a-984e-b093f809ca9e', 'D', '5 anos.', false, 3),
('ed28c085-067a-433a-984e-b093f809ca9e', 'E', '6 anos.', false, 4),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', 'A', 'A afirmação da competência municipal para legislar sobre o meio ambiente, reconhecida no Tema 145 do STF, possibilita aos Municípios proibirem a queima de palha de cana de açúcar e o uso de fogo em atividades agrícolas, por ser método rudimentar e primitivo.', false, 0),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', 'B', 'A existência de Lei Federal sobre mesmo conteúdo da Lei Municipal afasta a competência municipal para dispor sobre matéria com idêntico conteúdo, mesmo que Municípios tenham competência para legislar sobre meio ambiente.', false, 1),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', 'C', 'A Lei Federal proíbe a queima da palha da cana de açúcar, não abrindo espaço legislativo para o exercício de competência estadual ou municipal, sendo a legislação local reforço do dispositivo federal.', false, 2),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', 'D', 'A Lei Estadual do Estado de São Paulo criou uma forma progressiva de mecanização do cultivo da lavoura de cana de açúcar, compatibilizando a redução ao máximo do aspecto negativo ambiental com as repercussões sociais da mudança do modo de cultivo, devendo ser aplicada a todos municípios paulistas.', true, 3),
('0cd71988-7f75-40ae-91d3-04eec4b400b5', 'E', 'Sendo Tema do STF, a Lei estadual paulista deve ser aplicada aos demais entes federativos brasileiros, dado a repercussão geral de decisão desta espécie.', false, 4),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', 'A', 'Apenas I.', true, 0),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', 'B', 'Apenas II.', false, 1),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', 'C', 'Apenas III.', false, 2),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', 'D', 'Apenas I e III.', false, 3),
('2e9a4766-86e9-45e3-acd3-d37c94102a5f', 'E', 'Apenas II e III.', false, 4);